def submit(j):
    request=urllib.request.Request(j["url"], data=pathlib.Path(j["path"]).read_bytes(), headers={"Content-Type":j["mime"]}, method="POST")
    with urllib.request.urlopen(request,timeout=90) as r: value=json.load(r)
    return {"name":j["name"],"nodeId":j["nodeId"],"response":value}
with ThreadPoolExecutor(max_workers=4) as pool: records=list(pool.map(submit,jobs))
out=pathlib.Path(r"E:\codexwork\Site-Skin-edit\exports\bit365-partner-logos-20261013-172530\uploads.json")
out.write_text(json.dumps(records,indent=2),encoding="utf-8")
print(json.dumps({"uploaded":len(records),"success":all(x["response"].get("success") for x in records)}))

